package com.zxl.zxlaiagent.security;
import java.sql.*;
import java.time.*;
import java.nio.charset.StandardCharsets;
/** Infrastructure-only opaque delegation; never expose tickets to model tool schemas or public events. */
public final class ServiceCallAuthorizer {
 private final SecurityDatabase db;private final AuthorizationService authorization;
 public ServiceCallAuthorizer(SecurityDatabase db,AuthorizationService authorization){this.db=db;this.authorization=authorization;}
 public static String requestHash(String method,String path,byte[] body){return CredentialDigests.hash(method+"\n"+path+"\n"+java.util.Base64.getEncoder().encodeToString(body));}
 public String issue(ActorRef ref,String audience,String action,ResourceRef resource,String requestHash){return issue(ref,audience,action,resource,requestHash,Duration.ofSeconds(30));}
 public String issue(ActorRef ref,String audience,String action,ResourceRef resource,String requestHash,Duration lifetime){if(lifetime==null||lifetime.isNegative()||lifetime.isZero()||lifetime.compareTo(Duration.ofSeconds(60))>0||audience==null||audience.isBlank()||audience.length()>80||requestHash==null||!requestHash.matches("[0-9a-f]{64}"))throw new SecurityFailure("INVALID_SERVICE_TICKET",401);
  record Issued(AuthorizationDecision decision,String token){}var issued=db.tx(c->{var d=authorization.decide(c,ref,action,resource,Phase.TOOL_DISPATCH,null);if(!d.allowed())return new Issued(d,null);String token=CredentialDigests.random();try(var s=SecurityDatabase.statement(c,"DELETE FROM service_call_ticket WHERE ticket_hash IN (SELECT ticket_hash FROM service_call_ticket WHERE expires_at<now() ORDER BY expires_at LIMIT 100)")){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO service_call_ticket(ticket_hash,audience,action,actor_session_id,authentication_version,resource_type,resource_id,request_sha256,expires_at) VALUES (?,?,?,?,?,?,?,?,?)",CredentialDigests.hash(token),audience,action,ref.sessionId(),ref.authenticationVersion(),resource==null?null:resource.type(),resource==null?null:resource.id(),requestHash,Timestamp.from(Instant.now().plus(lifetime)))){s.executeUpdate();}return new Issued(d,token);});issued.decision().requireAllowed();return issued.token();}
 public ActorRef consume(String ticket,String audience,String action,String requestHash){if(ticket==null||ticket.length()>256||audience==null||audience.length()>80||action==null||action.length()>80||requestHash==null||!requestHash.matches("[0-9a-f]{64}"))throw new SecurityFailure("INVALID_SERVICE_TICKET",401);record Consumed(ActorRef ref,AuthorizationDecision decision){}var consumed=db.tx(c->{ActorRef ref;ResourceRef resource;
  // Epoch first, then session/ticket: all paths share one lock order and serialize same-subject revocation.
  try(var s=SecurityDatabase.statement(c,"SELECT s.subject_id,s.tenant_id,s.session_id,t.authentication_version,t.resource_type,t.resource_id FROM service_call_ticket t JOIN auth_session s ON s.session_id=t.actor_session_id WHERE ticket_hash=? AND audience=? AND action=? AND request_sha256=? AND consumed_at IS NULL",CredentialDigests.hash(ticket),audience,action,requestHash);var r=s.executeQuery()){if(!r.next())throw new SecurityFailure("INVALID_SERVICE_TICKET",401);ref=new ActorRef(r.getString(1),r.getString(2),r.getString(3),r.getLong(4));resource=r.getString(5)==null?null:new ResourceRef(r.getString(5),r.getString(6));}
  AuthenticationService.lockEpoch(c,ref);
  try(var lock=SecurityDatabase.statement(c,"SELECT ticket_hash FROM service_call_ticket WHERE ticket_hash=? FOR UPDATE",CredentialDigests.hash(ticket));var locked=lock.executeQuery()){if(!locked.next())throw new SecurityFailure("INVALID_SERVICE_TICKET",401);}
  try(var s=SecurityDatabase.statement(c,"UPDATE service_call_ticket SET consumed_at=clock_timestamp() WHERE ticket_hash=? AND consumed_at IS NULL AND expires_at>clock_timestamp()",CredentialDigests.hash(ticket))){if(s.executeUpdate()!=1)throw new SecurityFailure("INVALID_SERVICE_TICKET",401);}return new Consumed(ref,authorization.decide(c,ref,action,resource,Phase.TOOL_DISPATCH,null));});consumed.decision().requireAllowed();return consumed.ref();}
}
